// src/components/trading/Trading.js
import React, { useState } from 'react';
import { useTheme } from '../../contexts/ThemeContext';

export default function Trading() {
  const [orderType, setOrderType] = useState('buy');
  const [selectedAsset, setSelectedAsset] = useState('SBER');
  const [quantity, setQuantity] = useState('');
  const [price, setPrice] = useState('');
  const { isDark } = useTheme();

  const assets = [
    { symbol: 'SBER', name: 'Сбербанк', currentPrice: 275.50 },
    { symbol: 'GAZP', name: 'Газпром', currentPrice: 172.30 },
    { symbol: 'LKOH', name: 'Лукойл', currentPrice: 5890.25 },
    { symbol: 'YNDX', name: 'Яндекс', currentPrice: 4650.75 }
  ];

  const handleSubmitOrder = async (e) => {
    e.preventDefault();
    // Здесь будет интеграция с API торговли
    alert(`Заказ на ${orderType === 'buy' ? 'покупку' : 'продажу'} ${quantity} акций ${selectedAsset} по цене ${price} ₽ будет обработан`);
  };

  const selectedAssetData = assets.find(asset => asset.symbol === selectedAsset);

  return (
    <div className="space-y-6">
      <div className={`rounded-3xl p-8 text-white shadow-2xl ${
        isDark
          ? 'bg-gradient-to-r from-green-600 to-cyan-600'
          : 'bg-gradient-to-r from-blue-500 to-purple-600'
      }`}>
        <h1 className="text-3xl font-bold mb-2">Торговля</h1>
        <p className={isDark ? 'text-cyan-100' : 'text-blue-100'}>
          Совершайте сделки с AI-рекомендациями
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Панель торговли */}
        <div className="lg:col-span-1">
          <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
            <h3 className="text-xl font-semibold text-gray-800 dark:text-white mb-4">
              Новая сделка
            </h3>
            
            <form onSubmit={handleSubmitOrder} className="space-y-4">
              {/* Переключатель покупки/продажи */}
              <div className="flex rounded-2xl bg-gray-100 dark:bg-gray-700 p-1">
                <button
                  type="button"
                  onClick={() => setOrderType('buy')}
                  className={`flex-1 py-3 px-4 rounded-2xl text-sm font-semibold transition-all duration-300 ${
                    orderType === 'buy'
                      ? 'bg-green-500 text-white shadow-lg'
                      : 'text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-white'
                  }`}
                >
                  Покупка
                </button>
                <button
                  type="button"
                  onClick={() => setOrderType('sell')}
                  className={`flex-1 py-3 px-4 rounded-2xl text-sm font-semibold transition-all duration-300 ${
                    orderType === 'sell'
                      ? 'bg-red-500 text-white shadow-lg'
                      : 'text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-white'
                  }`}
                >
                  Продажа
                </button>
              </div>

              {/* Выбор актива */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Актив
                </label>
                <select
                  value={selectedAsset}
                  onChange={(e) => setSelectedAsset(e.target.value)}
                  className={`w-full rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:border-transparent transition-all duration-300 ${
                    isDark
                      ? 'bg-gray-700 border-gray-600 text-white focus:ring-cyan-500'
                      : 'border border-gray-300 focus:ring-blue-500'
                  }`}
                >
                  {assets.map((asset) => (
                    <option key={asset.symbol} value={asset.symbol}>
                      {asset.name} ({asset.symbol})
                    </option>
                  ))}
                </select>
              </div>

              {/* Текущая цена */}
              {selectedAssetData && (
                <div className={`p-4 rounded-2xl ${
                  isDark ? 'bg-gray-700' : 'bg-gray-100'
                }`}>
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600 dark:text-gray-400">Текущая цена:</span>
                    <span className="text-lg font-bold text-gray-800 dark:text-white">
                      {selectedAssetData.currentPrice.toLocaleString('ru-RU')} ₽
                    </span>
                  </div>
                </div>
              )}

              {/* Количество */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Количество
                </label>
                <input
                  type="number"
                  value={quantity}
                  onChange={(e) => setQuantity(e.target.value)}
                  placeholder="0"
                  className={`w-full rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:border-transparent transition-all duration-300 ${
                    isDark
                      ? 'bg-gray-700 border-gray-600 text-white focus:ring-cyan-500'
                      : 'border border-gray-300 focus:ring-blue-500'
                  }`}
                />
              </div>

              {/* Цена */}
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Цена (₽)
                </label>
                <input
                  type="number"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
                  placeholder="0.00"
                  step="0.01"
                  className={`w-full rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:border-transparent transition-all duration-300 ${
                    isDark
                      ? 'bg-gray-700 border-gray-600 text-white focus:ring-cyan-500'
                      : 'border border-gray-300 focus:ring-blue-500'
                  }`}
                />
              </div>

              {/* Сумма */}
              {quantity && price && (
                <div className={`p-4 rounded-2xl ${
                  isDark ? 'bg-gray-700' : 'bg-gray-100'
                }`}>
                  <div className="flex justify-between items-center">
                    <span className="text-sm text-gray-600 dark:text-gray-400">Общая сумма:</span>
                    <span className="text-lg font-bold text-gray-800 dark:text-white">
                      {(quantity * price).toLocaleString('ru-RU', {minimumFractionDigits: 2})} ₽
                    </span>
                  </div>
                </div>
              )}

              {/* Кнопка отправки */}
              <button
                type="submit"
                className={`w-full py-3 rounded-2xl font-semibold text-white shadow-lg hover:shadow-xl transform hover:-translate-y-0.5 transition-all duration-300 ${
                  orderType === 'buy'
                    ? 'bg-gradient-to-r from-green-600 to-cyan-600 hover:from-green-700 hover:to-cyan-700'
                    : 'bg-gradient-to-r from-red-600 to-pink-600 hover:from-red-700 hover:to-pink-700'
                }`}
              >
                {orderType === 'buy' ? 'Купить' : 'Продать'} {selectedAsset}
              </button>
            </form>
          </div>
        </div>

        {/* AI рекомендации и информация */}
        <div className="lg:col-span-2 space-y-6">
          {/* AI рекомендация */}
          <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
            <h3 className="text-xl font-semibold text-gray-800 dark:text-white mb-4">
              AI Рекомендация для {selectedAssetData?.name}
            </h3>
            <div className={`p-6 rounded-2xl ${
              isDark ? 'bg-green-500/20 border border-green-500/30' : 'bg-green-50 border border-green-200'
            }`}>
              <div className="flex items-center space-x-4">
                <div className={`p-3 rounded-2xl ${
                  isDark ? 'bg-green-500/30' : 'bg-green-100'
                }`}>
                  <svg className="w-8 h-8 text-green-600 dark:text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
                  </svg>
                </div>
                <div>
                  <h4 className="text-lg font-bold text-gray-800 dark:text-white">Сильная покупка</h4>
                  <p className="text-gray-600 dark:text-gray-400 mt-1">
                    Модель предсказывает рост на 15% в ближайшие 30 дней с точностью 87%
                  </p>
                  <div className="flex items-center mt-3 space-x-4">
                    <div className="flex items-center">
                      <div className="w-24 bg-gray-200 dark:bg-gray-700 rounded-full h-2 mr-3">
                        <div className="bg-green-500 h-2 rounded-full" style={{width: '87%'}}></div>
                      </div>
                      <span className="text-sm text-gray-600 dark:text-gray-400">87% точность</span>
                    </div>
                    <div className="flex items-center">
                      <div className="w-24 bg-gray-200 dark:bg-gray-700 rounded-full h-2 mr-3">
                        <div className="bg-blue-500 h-2 rounded-full" style={{width: '92%'}}></div>
                      </div>
                      <span className="text-sm text-gray-600 dark:text-gray-400">92% уверенность</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* График и дополнительная информация */}
          <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
            <h3 className="text-xl font-semibold text-gray-800 dark:text-white mb-4">
              Технический анализ
            </h3>
            <div className={`h-64 rounded-2xl flex items-center justify-center ${
              isDark ? 'bg-gray-700' : 'bg-gray-100'
            }`}>
              <span className={isDark ? 'text-gray-400' : 'text-gray-500'}>
                График цены и технические индикаторы появятся здесь
              </span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
